test("adversarial inputs are linear: long runs of sk-, escapes and dots finish within a time bound", () => {
  const long = "REDACTED";
  const inputs = [
    "sk-" + "%2F".repeat(60000),
    "sk-" + "%252F".repeat(30000) + ".",
    "sk-a.".repeat(40000),
    "sk-" + "Ab1.".repeat(40000),
    "sk-sk-".repeat(30000) + "∕".repeat(1000),
    long + ".".repeat(80000) + long,
    (long + ".").repeat(4000),
    ("A".repeat(30) + "%2F").repeat(5000),
    "." .repeat(100000),
  ];
  // A chain of keys joined by dots (each key extends to the end of the chain) must cost the same per key at N and 4N.
  const chain = (unit: string, count: number): string => (unit + ".").repeat(count) + "end";
  const ghp = "REDACTED";
  const skKey = "REDACTED";
  withFreshBoundary(() => {
    for (const unit of [ghp, skKey]) {
      const time = (count: number): number => {
        const started = performance.now();
        redactDiagnosticForOutput(chain(unit, count));
        return performance.now() - started;
      };
      time(500); // warm up
      const small = Math.max(time(2000), 5);
      const large = time(8000);
      assert.ok(large < small * 12, `${unit.slice(0, 6)} chain: ${Math.round(small)}ms for 2000, ${Math.round(large)}ms for 8000`);
    }
    for (const input of inputs) {
      const started = performance.now();
      redactDiagnosticForOutput(input);
      const elapsed = performance.now() - started;
      assert.ok(elapsed < 3000, `${input.slice(0, 24)}...(${input.length}) took ${Math.round(elapsed)}ms`);
    }
  });
});
/**
 * Inputs for the redaction monotonicity test: existing redaction shapes and templates plus generated adjacent, nested
 * and chained key shapes. All keys are synthetic. `redaction_base_spans.json` records the [start, end) spans the redactor classified in
 * each input before the encoded/dotted work (origin/main 29e7ebff).
 */
const KEYS = [
  "REDACTED",
  "REDACTED",
  "REDACTED",
  "sk-REDACTED",
  "sk-Qx7Km2Vb9LrTz4/Models",
  "sk-cache",
  "REDACTED",
  "REDACTED",
  "REDACTED",
];
const JOINERS = [".", "/", "-", "_", "+", "%2F", "%2B", "∕", ";", ", ", " ", ".Xo2RtBq.", ".log", ".Models", "=", "\\/", "!", "?x="];
const WRAPPERS: Array<(s: string) => string> = [
  (s) => `request failed with key ${s} while connecting`,
  (s) => `the credential was ${s}.`,
  (s) => `token=${s} retry=1`,
  (s) => `{"api_key":"${s}","ok":false}`,
  (s) => `Authorization: Bearer ${s}`,
  (s) => `saved prefix_${s}.log and ${s}`,
  (s) => `GET https://llm.example/v1/models?key=${s}&x=1 failed`,
  (s) => s,
];

export function corpus(): string[] {
  const out = new Set<string>();
  for (const a of KEYS) {
    for (const wrap of WRAPPERS) out.add(wrap(a));
    for (const joiner of JOINERS) {
      for (const b of KEYS) {
        out.add(`${a}${joiner}${b}`);
        out.add(`${a}${joiner}${b}; saved prefix_${a}.log`);
      }
    }
  }
  return [...out];
}

